function patchesTable(){return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Composant</th><th>Priorité</th><th>Évaluation</th><th></th></tr></thead><tbody>${state.patches.map((p,i)=>`<tr><td><strong>${p.name}</strong><small>Version cible ${p.version}</small></td><td>${status(p.priority,p.priority==='Haute'?'warn':'info')}</td><td>${p.state}</td><td>${button('Examiner','patch','quiet small',`data-id="${i}"`)}</td></tr>`).join('')}</tbody></table></div>`;}
function alertsContent(){return state.alerts.map((a,i)=>`<div class="security-alert"><div class="alert-icon">${icon('alert')}</div><div><h3>${a.title}</h3><p>${a.id} · ${a.detail}</p></div>${a.status==='À examiner'?button('Qualifier','alert','secondary small',`data-id="${i}"`):status(a.status,a.status==='Incident confirmé'?'warn':'info')}</div>`).join('');}
