function auditPage(){return header('Traçabilité des actions','Journal de sécurité','Événements techniques expurgés de tout contenu médical.')+section('Dernières actions','Exemples de journalisation',`<div class="table-wrap"><table class="data-table"><thead><tr><th>Date</th><th>Auteur</th><th>Action</th><th>Référence</th></tr></thead><tbody>${state.audit.map(a=>`<tr><td>${a.date}</td><td>${escapeHTML(a.actor)}</td><td class="wrap">${escapeHTML(a.action)}</td><td>${escapeHTML(a.target)}</td></tr>`).join('')}</tbody></table></div>`);}
function accountsPage(){return header('Comptes & autorisations','Comptes et accès','Administration technique des comptes, sans consultation des dossiers médicaux.',button('+ Créer un compte','account-create','primary'))+section('Comptes de démonstration','Les changements sont simulés et tracés dans cet aperçu.',`<div class="table-wrap"><table class="data-table"><thead><tr><th>Compte</th><th>Rôle</th><th>État</th><th>Action</th></tr></thead><tbody>${state.accounts.map((a,i)=>`<tr><td><strong>${a.id}</strong></td><td>${a.role}</td><td>${status(a.status,a.status==='Actif'?'ok':'warn')}</td><td>${button(a.status==='Actif'?'Suspendre':'Réactiver','account-toggle','secondary small',`data-id="${i}"`)}</td></tr>`).join('')}</tbody></table></div><div class="section-footer">Votre compte d’administration ne peut pas s’attribuer un rôle soignant.</div>`)+section('Expiration des accès temporaires','Contrôle du 14 novembre · 09:10',`<div class="section-body row"><div>${status('Aucun accès résiduel détecté')}<p class="footnote">Partages expirés et diagnostics techniques révoqués dans le scénario.</p></div>${button('Voir le contrôle','access-check','secondary')}</div>`);}
