function deletionsPage(){return header('Droits des utilisateurs','Demandes de suppression','Suivi administratif sans consultation du contenu à supprimer.')+section('Demandes reçues','Exemples fictifs uniquement',`<div class="table-wrap"><table class="data-table"><thead><tr><th>Référence</th><th>Demande</th><th>État</th><th>Action</th></tr></thead><tbody><tr><td>DEL-004</td><td>Compte et données associées</td><td>${status(state.deletion?'Exécution simulée':'Règles de conservation à vérifier',state.deletion?'info':'warn')}</td><td>${button('Examiner','deletion-review','secondary small')}</td></tr></tbody></table></div>`);}
function settingsPage(){return header('Votre confort de lecture','Paramètres','Adaptezz votre espace et gérez les réglages disponibles.'.replace('Adaptezz','Adaptez'))+`<div class="settings-width">${section('Lisibilité','Ces préférences s’appliquent à cet aperçu.',`<div class="section-body"><label class="inline-setting"><span><strong>Agrandir les textes</strong><p>Une lecture plus confortable dans tout le dashboard.</p></span><input type="checkbox" data-setting="large" ${state.large?'checked':''}></label><label class="inline-setting"><span><strong>Renforcer les contrastes</strong><p>Des textes et contours plus marqués.</p></span><input type="checkbox" data-setting="contrast" ${state.contrast?'checked':''}></label></div>`)}${state.role==='user'?section('Rappels et notifications','Préférences simulées : aucun message n’est envoyé.',`<div class="section-body"><label class="inline-setting"><span><strong>Rappels de pause</strong><p>Activation et report à votre convenance.</p></span><input type="checkbox" data-setting="pauseEnabled" ${state.pauseEnabled?'checked':''}></label><div class="inline-setting"><label for="pause-frequency">Fréquence des rappels</label><select id="pause-frequency" data-pref="pauseFrequency">${[30,45,60,90].map(n=>`<option value="${n}" ${state.pauseFrequency===n?'selected':''}>${n} minutes</option>`).join('')}</select></div>${['Pauses','Nouveau conseil','Bilan disponible','Réponse du support','Calibration nécessaire'].map((label,i)=>`<div class="inline-setting"><label for="channel-${i}">${label}</label><select id="channel-${i}" data-channel="${i}">${['Les deux','Téléphone','Montre','Aucun'].map(v=>`<option ${v===(state.channels?.[i]||'Les deux')?'selected':''}>${v}</option>`).join('')}</select></div>`).join('')}<p class="footnote muted-border">Les alertes de nouvelle connexion restent uniquement dans le dashboard.</p><div class="form-columns" style="margin-top:18px">${field('Début des horaires silencieux','quietStart',state.quietStart,'time','data-pref="quietStart"')}${field('Fin des horaires silencieux','quietEnd',state.quietEnd,'time','data-pref="quietEnd"')}</div>${button('Reporter le prochain rappel','pause-snooze','secondary small')}</div>`):''}${state.role!=='employer'?section('Sessions du compte','Consultez les connexions de démonstration.',`<div class="section-body row"><p class="muted">Votre session et les autres appareils connectés.</p>${button('Gérer les sessions','sessions','secondary')}</div>`):''}${state.role==='user'?section('Compte et données','Vos demandes restent sous votre contrôle.',`<div class="section-body row"><p class="muted">Demander la suppression du compte et des données.</p>${button(state.deletionRequested?'Voir ma demande':'Demander la suppression','delete-request','danger')}</div>`):''}</div>`;}
function helpPage(){return header('Assistance technique','Vos demandes au support','Décrivez uniquement le problème technique, sans information médicale.',button('+ Nouveau ticket','help-new','primary'))+section('Mes tickets','Échanges de démonstration',`<ul class="record-list"><li><div class="row"><strong>TK-024 · Calibration à vérifier</strong>${status('En cours','info')}</div><p>Le support a répondu · 14 novembre à 09:42</p>${button('Lire la réponse','help-read','quiet small')}</li>${state.supportMessages.map((m,i)=>`<li><div class="row"><strong>TK-${25+i} · ${escapeHTML(m.title)}</strong>${status('À traiter','info')}</div><p>${escapeHTML(m.body)}</p></li>`).join('')}</ul>`);}
function render(){const r=roles[state.role];$('#space-label').textContent=r.space;$('#topbar-space').textContent=r.space;$('#topbar-title').textContent=state.page==='patient'?'Dossier autorisé':r.nav.find(n=>n[0]===state.page)?.[1]||'Vue d’ensemble';$('#sidebar-description').textContent=r.description;$('#account-label').textContent=r.account;$('#account-role').textContent=r.label;$('#account-avatar').textContent=r.initials;$('#notifications').innerHTML=icon('bell');$('#navigation').innerHTML=r.nav.map(([id,label,ico])=>`<button class="nav-item" data-page="${id}" ${state.page===id||(state.page==='patient'&&id==='home')?'aria-current="page"':''}>${icon(ico)}<span>${label}</span>${state.role==='support'&&id==='home'?`<span class="nav-count">${state.tickets.filter(t=>t.status!=='Résolu').length}</span>`:''}</button>`).join('');document.documentElement.classList.toggle('large-text',state.large);document.documentElement.classList.toggle('high-contrast',state.contrast);let html='';
 if(state.page==='settings')html=settingsPage();else if(state.page==='help')html=helpPage();else if(state.role==='user'){if(state.page==='home')html=userHome();else if(state.page==='measures')html=header('Historique personnel','Mes mesures','Consultez les périodes disponibles et leur qualité.',button(icon('download')+' Télécharger','export-user','secondary'))+measures()+`<div class="notice warn">Le 7 novembre, la calibration a changé. Ne comparez pas directement les appuis avant et après cette date.</div>`;else if(state.page==='shares')html=sharesPage();else if(state.page==='device')html=devicePage();else html=header('Votre suivi','Conseils et bilans','Les documents partagés par votre soignant.')+section('Conseils personnalisés','Soignant démo',adviceContent())+section('Bilan de fin de suivi','Version publiée',reportContent());}
 else if(state.role==='clinician'){if(state.page==='patient')html=patientPage();else if(state.page==='home')html=clinicianHome();else if(state.page==='reminders')html=header('Organisation du suivi','Mes rappels','Les rappels ne prolongent pas les droits d’accès.',button('+ Ajouter un rappel','reminder-add','primary'))+section('Dossiers à réexaminer','Vos échéances personnelles',remindersContent());else html=header('Prévention collective','Recommandations publiées','Des actions d’aménagement, sans information médicale individuelle.',button('+ Publier une recommandation','recommendation-write','primary'))+section('Suivi de mise en œuvre','Avancement renseigné par l’organisation.',recommendationTable(false));}
 else if(state.role==='employer')html=state.page==='history'?historyPage():employerHome();else if(state.role==='support')html=state.page==='maintenance'?maintenancePage():supportHome();else if(state.role==='admin'){const screens={home:adminHome,audit:auditPage,accounts:accountsPage,certificates:certificatesPage,components:componentsPage,deletions:deletionsPage};html=state.page==='incidents'?header('Qualification et réponse','Incidents de sécurité','Examinez les faits avant de conclure à un incident.')+section('Événements suivis','État de qualification',alertsContent()):screens[state.page]?.()||adminHome();}
 $('#content').innerHTML=html;document.title=`SKELIVIA · ${r.label} · Maquette`;$$('.table-wrap').forEach(el=>{el.tabIndex=0;el.setAttribute('role','region');el.setAttribute('aria-label','Tableau, défilement horizontal disponible si nécessaire');});setupTableOverflow();}
let tableObserver;
function setupTableOverflow(){
 tableObserver?.disconnect();
 const wrappers=$$('.table-wrap');
 const update=()=>wrappers.forEach(wrap=>{
  const hint=document.getElementById(wrap.dataset.scrollHint);
  const overflow=wrap.scrollWidth>wrap.clientWidth+1;
  if(hint)hint.hidden=!overflow;
  if(overflow)wrap.setAttribute('aria-describedby',hint.id);else wrap.removeAttribute('aria-describedby');
 });
 wrappers.forEach((wrap,index)=>{
  const hint=document.createElement('p');hint.id=`table-scroll-hint-${index}`;hint.className='table-scroll-hint';hint.textContent='Faites défiler le tableau →';hint.hidden=true;
  wrap.before(hint);wrap.dataset.scrollHint=hint.id;
 });
 if(typeof ResizeObserver==='function'){tableObserver=new ResizeObserver(update);wrappers.forEach(wrap=>{tableObserver.observe(wrap);const table=$('table',wrap);if(table)tableObserver.observe(table);});}
 update();
}
let dialogCallback=null,dialogOpener=null,toastTimer;
function notify(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,5000);}
// Adapted from Atelier universal-interactions: native dialog, trigger focus restoration.
function openDialog(title,content,submitText,callback){const d=$('#dialog');if(!d.open)dialogOpener=document.activeElement;$('#dialog-title').textContent=title;$('#dialog-content').innerHTML=content;$('#dialog-submit').textContent=submitText||'Valider';$('#dialog-submit').hidden=!submitText;$('#dialog-cancel').textContent=submitText?'Annuler':'Fermer';dialogCallback=callback||null;if(!d.open)d.showModal();($('input:not([type=hidden]),select,textarea,button', $('#dialog-content'))||$('#dialog-close')).focus();}
function closeDialog(){$('#dialog').close();}
$('#dialog').addEventListener('close',()=>{if(dialogOpener?.isConnected)dialogOpener.focus();dialogCallback=null;});$('#dialog-close').onclick=closeDialog;$('#dialog-cancel').onclick=closeDialog;$('#dialog-form').onsubmit=e=>{e.preventDefault();if(!e.currentTarget.reportValidity())return;const cb=dialogCallback;if(cb)cb(new FormData(e.currentTarget));};
$('#dialog').addEventListener('click',e=>{if(e.target!==$('#dialog'))return;const b=e.target.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)closeDialog();});
// Adapted from Atelier ui-app-shell: breakpoint, toggle state, Escape and focus return.
const mobileMedia=matchMedia('(max-width:800px)');
function menu(open,focus=false){$('#sidebar').classList.toggle('open',open);$('#open-menu').setAttribute('aria-expanded',String(open));$('#backdrop').hidden=!open||!mobileMedia.matches;$('#sidebar').inert=mobileMedia.matches&&!open;if(focus)(open?$('#close-menu'):$('#open-menu')).focus();}
$('#open-menu').onclick=()=>menu(true,true);$('#close-menu').onclick=()=>menu(false,true);$('#backdrop').onclick=()=>menu(false,true);mobileMedia.addEventListener('change',()=>menu(false));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#sidebar').classList.contains('open')){e.preventDefault();menu(false,true);}if(e.key==='Tab'&&mobileMedia.matches&&$('#sidebar').classList.contains('open')){const list=$$('a,button', $('#sidebar')).filter(el=>el.getClientRects().length),first=list[0],last=list.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
function go(page){state.page=page;state.ticketMobile=false;menu(false);render();window.scrollTo({top:0,behavior:'instant'});$('#content').focus({preventScroll:true});}
$('#role-select').onchange=e=>{if($('#dialog').open)closeDialog();state.role=e.target.value;state.page='home';state.patientTab='measures';state.ticketMobile=false;state.period='day';menu(false);render();window.scrollTo(0,0);};
$('#account').onclick=()=>openDialog('Votre compte',`<p>${roles[state.role].account} · ${roles[state.role].label}</p><div class="account-panel">${button(icon('settings')+' Préférences de lecture','settings','secondary')}${state.role!=='employer'?button(icon('shield')+' Sessions du compte','sessions','secondary'):''}</div>`);
$('#notifications').onclick=()=>{let items=state.role==='user'?[['Nouveau conseil disponible','Un document de votre soignant est disponible.','advice'],['Votre bilan est disponible','Consultez-le dans votre espace personnel.','report'],['Nouvelle connexion','Un appareil de démonstration s’est connecté à votre compte.','security-self']]:state.role==='clinician'?[['Mise à jour des mesures','Consultez les effets sur les unités et la comparabilité.','update-info'],['Connexion suspecte','Vérifiez cette connexion à votre compte.','security-self']]:state.role==='employer'?[['Nouvelle recommandation','Une nouvelle action de prévention a été publiée.','home']]:state.role==='support'?[['Ticket attribué','TK-024 est disponible dans votre file de support.','home']]:[['Alerte à examiner','Un composant a cessé de transmettre ses journaux.','incidents']];openDialog('Notifications',`<ul class="dialog-list">${items.map(([title,text,action])=>`<li><strong>${title}</strong><p>${text}</p>${button('Consulter','notification-route','quiet small',`data-route="${action}"`)}</li>`).join('')}</ul>`);};
function log(action,target){state.audit.unshift({date:'14 nov. · 18:05',actor:'Administrateur démo',action,target});}
function simulationDone(message){closeDialog();render();notify(`${message} · simulation locale`);}
function downloadFile(name,content){const url=URL.createObjectURL(new Blob([content],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Document fictif téléchargé.');}
function calibration(){const steps=[['Préparer la souris','Posez la souris sur une surface stable. Ce parcours présente les étapes de vérification ; aucun appareil n’est interrogé.','Je confirme que la souris est prête.'],['Vérifier les capteurs','Le contrôle technique vérifie les canaux et les conditions de référence du protocole. Il ne mesure pas une force idéale pour votre santé.','Je souhaite simuler la vérification technique.'],['Résultat de démonstration','Vérification simulée réussie. La calibration C-02 reste la référence de ces données fictives. Un échec réel devrait conduire à une intervention du support.','']];const s=steps[state.calibrationStep];openDialog('Calibration guidée',`<div class="calibration-steps" aria-hidden="true">${steps.map((_,i)=>`<span class="${i<=state.calibrationStep?'active':''}"></span>`).join('')}</div><p class="calibration-number">Étape ${state.calibrationStep+1} sur 3</p><h3>${s[0]}</h3><p class="calibration-description">${s[1]}</p>${s[2]?`<label class="check-row"><input type="checkbox" required>${s[2]}</label>`:status('Résultat simulé : vérifié')}`,state.calibrationStep===2?'Terminer':'Continuer',()=>{if(state.calibrationStep<2){state.calibrationStep++;calibration();}else{state.calibrated=true;simulationDone('Vérification terminée');}});}
function handleAction(action,node){const id=Number(node?.dataset.id||0);if(roles[state.role].nav.some(n=>n[0]===action)){if($('#dialog').open)closeDialog();go(action);return;}
 if(action==='report')openDialog('Bilan de fin de suivi',`<p class="small-label">Soignant démo · 12 novembre 2026 · Version ${state.reportVersion}</p><p>${escapeHTML(state.report)}</p><div class="notice">Document fictif de présentation. Aucun avis médical réel n’est délivré.</div>`);
 else if(action==='export-user'){const d=datasets[state.period];openDialog('Télécharger mon bilan',`<p>Période sélectionnée : <strong>${d.label}</strong>.</p><p>Le document d’exemple contient les unités, les périodes manquantes et la référence de calibration.</p>`,'Télécharger le fichier d’exemple',()=>{downloadFile('SKELIVIA-bilan-fictif.txt',`SKELIVIA — DONNÉES FICTIVES\n${d.label}\nTemps de contact (minutes): ${d.contact.map(v=>v??'manquant').join('; ')}\nAppui pouce (% relatif simulé): ${d.pressure.map(v=>v??'manquant').join('; ')}\nAppui paume (% relatif simulé): ${d.palm.map(v=>v??'manquant').join('; ')}\nÉpisodes mouvement: ${d.moves.map(v=>v??'manquant').join('; ')}\n${d.missing}\nCalibration C-02 depuis le 7 novembre. Comparabilité limitée avec calibration antérieure.\nLes valeurs ne constituent pas un diagnostic.`);closeDialog();});}
 else if(action==='export-org'){downloadFile('SKELIVIA-prevention-fictive.txt','SKELIVIA — RÉCAPITULATIF FICTIF\n'+state.orgRecs.map(r=>`${r.id} | ${r.title} | ${r.status} | ${r.date}`).join('\n'));}
 else if(action==='share-new')openDialog('Choisir un partage',`<p>Destinataire habilité : <strong>Soignant démo</strong>. Relation de suivi active dans ce scénario.</p><div class="form-columns">${field('Début des mesures','start','2026-11-08','date','required min="2026-10-16" max="2026-11-14"')}${field('Fin des mesures','end','2026-11-14','date','required min="2026-10-16" max="2026-11-14"')}</div>${field('Fin de l’accès','expiry','2026-11-30','date','required min="2026-11-15"')}<label class="check-row"><input name="contact" type="checkbox" checked>Temps de contact détecté</label><label class="check-row"><input name="pressure" type="checkbox" checked>Appuis relatifs</label><label class="check-row"><input name="moves" type="checkbox" checked>Épisodes de mouvement</label><p class="footnote">La maquette n’accorde aucun accès réel.</p>`,'Créer le partage fictif',data=>{if(data.get('start')>data.get('end')){notify('La fin doit être postérieure au début.');return;}const scopes=['contact','pressure','moves'].filter(k=>data.has(k));if(!scopes.length){notify('Choisissez au moins un type de mesure.');return;}state.shares.push({name:'Soignant démo',scope:`${data.get('start')} au ${data.get('end')} · ${scopes.map(k=>({contact:'contact',pressure:'appuis',moves:'mouvements'}[k])).join(', ')}`,expires:data.get('expiry'),active:true});simulationDone('Partage créé');});
 else if(action==='share-revoke')openDialog('Révoquer ce partage ?',`<p>Le soignant ne pourra plus consulter les mesures de cette période via ce partage.</p><p><strong>${escapeHTML(state.shares[id].scope)}</strong></p>`,'Révoquer le partage fictif',()=>{state.shares[id].active=false;simulationDone('Partage révoqué');});
 else if(action==='calibrate'){state.calibrationStep=0;calibration();}
 else if(action==='update-info')openDialog('Mise à jour 2.4.2',`<ul class="dialog-list"><li><strong>Approuvée pour le scénario</strong><p>La version cible doit être installée dans une intervention technique.</p></li><li><strong>Contrôle après installation</strong><p>Connexion, fonctionnement des capteurs et calibration seront vérifiés.</p></li><li><strong>Comparaison des bilans</strong><p>Pas de changement d’unité dans cet exemple. Toute rupture de calibration reste visible.</p></li></ul>`);
 else if(action==='device-loss')openDialog('Perte ou remplacement',`<p>Un ticket technique sera créé dans cet aperçu. Ne renseignez aucune information médicale.</p><div class="field"><label for="f-kind">Situation</label><select name="kind" id="f-kind"><option>Perte de souris</option><option>Remplacement de souris</option></select></div>`,'Créer le ticket fictif',data=>{state.supportMessages.push({title:data.get('kind'),body:'Demande concernant l’association de l’appareil SK-M042.'});simulationDone('Demande enregistrée');});
 else if(action==='patient'){if(id>=3){notify('Partage expiré : dossier inaccessible.');return;}state.patient=id;state.patientTab='measures';go('patient');}
 else if(action==='compare')openDialog('Comparer deux périodes',`<div class="comparison"><div><h3>Du 1 au 7 novembre</h3><p>Contact <strong>16 h 40</strong></p><p>Appui relatif <strong>23 %</strong></p><p>Épisodes <strong>805</strong></p><p>Calibration <strong>C-01 / C-02</strong></p></div><div><h3>Du 8 au 14 novembre</h3><p>Contact <strong>17 h 32</strong></p><p>Appui relatif <strong>21 %</strong></p><p>Épisodes <strong>989</strong></p><p>Calibration <strong>C-02</strong></p></div></div><div class="notice warn">Calibration modifiée le 7 novembre. La comparaison des appuis est limitée ; aucune conclusion clinique ne peut être tirée de cet avant/après.</div>`);
 else if(action==='advice-write'||action==='advice-edit'){const editing=action==='advice-edit',old=state.advice[0];openDialog(editing?'Nouvelle version du conseil':'Rédiger un conseil',field('Titre','title',editing?old.title:'','text','required maxlength="120"')+textarea('Conseil destiné au patient','body',editing?old.body:'')+'<p class="footnote">La publication est simulée. Le document sera visible dans l’espace utilisateur de cette maquette.</p>','Publier la version fictive',data=>{state.advice.unshift({title:data.get('title'),body:data.get('body'),date:'14 novembre 2026',version:editing?old.version+1:1});simulationDone('Conseil publié');});}
 else if(action==='report-write'||action==='report-edit')openDialog(action==='report-edit'?'Nouvelle version du bilan':'Rédiger le bilan',textarea('Conclusions et conseils à conserver','body',state.report)+'<p class="footnote">Le bilan fictif sera visible dans l’espace utilisateur. Aucun dossier réel n’est modifié.</p>','Valider et publier dans l’aperçu',data=>{state.report=data.get('body');state.reportVersion++;simulationDone('Bilan publié');});
 else if(action==='reminder-add')openDialog('Ajouter un rappel',`<div class="field"><label for="f-patient">Dossier</label><select name="patient" id="f-patient">${patients.slice(0,3).map(p=>`<option>${p.id}</option>`).join('')}</select></div>${field('Date du rappel','date','2026-11-18','date','required min="2026-11-15"')}${field('Objet','subject','Réexaminer le bilan partagé.','text','required maxlength="120"')}<p class="footnote">Un rappel ne prolonge pas le partage du patient.</p>`,'Ajouter le rappel',data=>{const d=new Date(data.get('date')+'T12:00:00');state.reminders.push({day:String(d.getDate()),month:d.toLocaleDateString('fr-FR',{month:'short'}).toUpperCase(),patient:data.get('patient'),text:data.get('subject')});simulationDone('Rappel ajouté');});
 else if(action==='recommendation-write')openDialog('Publier une recommandation',field('Titre de l’action','title','','text','required maxlength="120"')+textarea('Aménagement ou organisation concernés','body')+'<div class="notice">N’incluez aucun nom de patient, symptôme, mesure individuelle ou conclusion médicale.</div>','Publier dans l’aperçu',data=>{state.orgRecs.unshift({id:'REC-'+String(15+state.orgRecs.length-4).padStart(3,'0'),title:data.get('title'),text:data.get('body'),category:'Organisation',status:'À traiter',date:'14 nov. 2026'});simulationDone('Recommandation publiée');});
 else if(action==='ticket-select'){state.ticket=id;state.ticketMobile=true;render();if(mobileMedia.matches)window.scrollTo(0,0);}
 else if(action==='ticket-back'){state.ticketMobile=false;render();}
 else if(action==='ticket-reply')openDialog('Réponse technique',textarea('Réponse au ticket '+state.tickets[state.ticket].id,'reply'),'Ajouter la réponse fictive',data=>{state.tickets[state.ticket].messages.push({by:'Support',text:data.get('reply')});simulationDone('Réponse ajoutée');});
 else if(action==='ticket-wait'){state.tickets[state.ticket].status='En attente';render();notify('Ticket mis en attente · simulation locale');}
 else if(action==='ticket-close'){const t=state.tickets[state.ticket],checks=state.testChecks[t.id]||{};if(!checks.connection||!checks.sensors||!checks.calibration){notify('Effectuez les trois vérifications avant de clôturer.');return;}t.status='Résolu';render();notify('Vérifications enregistrées, ticket résolu · simulation locale');}
 else if(action==='support-update')openDialog('Installer la version approuvée',`<p>Appareil ${state.tickets[state.ticket].device} · version cible <strong>2.4.2</strong>.</p><p>La mise à jour est approuvée dans ce scénario. Vous devrez vérifier le fonctionnement après l’installation.</p>`,'Simuler l’installation',()=>{state.tickets[state.ticket].firmware='2.4.2';state.testChecks[state.tickets[state.ticket].id]={};simulationDone('Installation simulée, contrôles à effectuer');});
 else if(action==='support-replace')openDialog('Associer une souris de remplacement',`<p>Ancien appareil : ${state.tickets[state.ticket].device}. Son association sera retirée dans le scénario.</p>${field('Identifiant du nouvel appareil','device','SK-M052','text','required pattern="SK-M[0-9]{3}"')}<label class="check-row"><input type="checkbox" required>Association du nouvel appareil vérifiée avec l’utilisateur.</label>`,'Simuler le remplacement',data=>{state.tickets[state.ticket].device=data.get('device');state.testChecks[state.tickets[state.ticket].id]={};simulationDone('Association remplacée');});
 else if(action==='security-report')openDialog('Signaler une anomalie technique',textarea('Éléments techniques strictement nécessaires','evidence')+'<p class="footnote">Aucune courbe d’usage ni donnée de santé ne doit être jointe.</p>','Transmettre dans l’aperçu',data=>{state.alerts.push({id:'SEC-025',title:'Signalement du support',detail:data.get('evidence'),status:'À examiner'});simulationDone('Signalement ajouté à la file sécurité');});
 else if(action==='help-new')openDialog('Nouveau ticket technique',field('Objet','title','','text','required maxlength="120"')+textarea('Description technique','body')+'<p class="footnote">Pas de dossier patient, de symptômes ou de message médical.</p>','Créer le ticket fictif',data=>{state.supportMessages.push({title:data.get('title'),body:data.get('body')});simulationDone('Ticket créé');});
 else if(action==='help-read')openDialog('TK-024 · Réponse du support','<p>Le diagnostic technique de votre souris est disponible. Nous vous proposons de suivre le parcours de vérification de la calibration.</p>'+button('Ouvrir la calibration','calibrate','primary'));
 else if(action==='sessions')openDialog('Sessions du compte',`<ul class="dialog-list">${state.sessions.map(s=>`<li><strong>${s.name}</strong><p>${s.detail}</p>${s.current?status('Session actuelle'):button('Déconnecter','session-revoke','secondary small',`data-session="${s.id}"`)}</li>`).join('')}</ul>`);
 else if(action==='session-revoke'){state.sessions=state.sessions.filter(s=>s.id!==node.dataset.session);handleAction('sessions');notify('Session déconnectée dans le scénario.');}
 else if(action==='security-self')openDialog('Connexion à vérifier',`<p>Un nouvel appareil de démonstration est apparu dans les sessions du compte. Vérifiez s’il vous appartient.</p><div class="notice">Cette alerte reste dans le dashboard utilisateur. Aucun message n’est envoyé sur téléphone ou montre.</div>`,state.newSessionReported?'':'Ce n’est pas moi',()=>{state.newSessionReported=true;simulationDone('Signalement de sécurité enregistré');});
 else if(action==='notification-route'){const route=node.dataset.route;closeDialog();handleAction(route,node);}
 else if(action==='pause-snooze')notify('Prochain rappel reporté de 10 minutes · simulation, aucune notification envoyée.');
 else if(action==='delete-request')openDialog(state.deletionRequested?'Demande de suppression':'Demander la suppression',state.deletionRequested?'<p>Demande DEL-004 enregistrée dans la maquette. Son traitement dépend des règles de conservation applicables.</p>':'<p>La demande concerne votre compte et vos données. Son traitement doit tenir compte des règles de conservation et être confirmé.</p><label class="check-row"><input type="checkbox" required>Je souhaite créer cette demande fictive.</label>',state.deletionRequested?'':'Confirmer la demande fictive',()=>{state.deletionRequested=true;simulationDone('Demande de suppression enregistrée');});
 else if(action==='alert')openDialog('Qualifier '+state.alerts[id].id,`<p><strong>${escapeHTML(state.alerts[id].title)}</strong></p><p>${escapeHTML(state.alerts[id].detail)}</p><div class="field"><label for="f-qualification">Qualification</label><select id="f-qualification" name="qualification"><option>Incident confirmé</option><option>Fausse alerte</option><option>À examiner</option></select></div>${textarea('Éléments de qualification','reason')}`,'Enregistrer dans l’aperçu',data=>{state.alerts[id].status=data.get('qualification');log('Qualification : '+data.get('qualification')+' — '+data.get('reason'),state.alerts[id].id);simulationDone('Qualification enregistrée');});
 else if(action==='patch')openDialog('Évaluer le correctif',`<p><strong>${state.patches[id].name} · ${state.patches[id].version}</strong></p><dl class="details-grid"><div><dt>Priorité proposée</dt><dd>${state.patches[id].priority}</dd></div><div><dt>Exposition</dt><dd>Composant du scénario à vérifier</dd></div></dl><div class="notice">Vérifier l’applicabilité, les tests des droits, la calibration et les possibilités de récupération avant déploiement.</div><div class="field"><label for="f-decision">Décision</label><select name="decision" id="f-decision"><option>Tests à examiner</option><option>Approuvée</option><option>Différée</option><option>Déployée et vérifiée</option></select></div>${textarea('Résultats des tests et motif','reason')}`,'Enregistrer la décision fictive',data=>{state.patches[id].state=data.get('decision');log('Correctif '+data.get('decision')+' — '+data.get('reason'),state.patches[id].name);simulationDone('Décision enregistrée');});
 else if(action==='account-toggle')openDialog((state.accounts[id].status==='Actif'?'Suspendre ':'Réactiver ')+state.accounts[id].id,textarea('Motif de l’action','reason'),'Confirmer dans l’aperçu',data=>{state.accounts[id].status=state.accounts[id].status==='Actif'?'Suspendu':'Actif';log('Compte '+state.accounts[id].status+' — '+data.get('reason'),state.accounts[id].id);simulationDone('État du compte modifié');});
 else if(action==='account-create')openDialog('Créer un compte de démonstration',field('Identifiant technique','id','','text','required pattern="[A-Z0-9-]{3,20}"')+`<div class="field"><label for="f-role">Rôle demandé</label><select name="role" id="f-role"><option>Utilisateur</option><option>Support</option><option>Employeur / prévention</option></select></div><p class="footnote">L’habilitation d’un soignant suit une procédure distincte. Aucun accès médical n’est accordé ici.</p>`,'Créer dans l’aperçu',data=>{state.accounts.push({id:data.get('id'),role:data.get('role'),status:'Actif'});log('Compte créé',data.get('id'));simulationDone('Compte créé');});
 else if(action==='cert-renew'||action==='cert-revoke')openDialog(action==='cert-revoke'?'Révoquer le certificat SK-M042':'Renouveler le certificat SK-M042',textarea('Motif et vérifications','reason'),'Confirmer dans l’aperçu',data=>{if(action==='cert-revoke')state.certificateRevoked=true;log(action==='cert-revoke'?'Certificat révoqué':'Renouvellement demandé','SK-M042');simulationDone(action==='cert-revoke'?'Certificat révoqué':'Renouvellement demandé');});
 else if(action==='backup')openDialog('Preuves de sauvegarde',`<ul class="dialog-list"><li><strong>BKP-20261114 · 14 novembre, 02:15</strong><p>Vérification d’intégrité réussie dans le scénario.</p></li><li><strong>Exercice de restauration · 10 novembre</strong><p>Restauration isolée et contrôle des droits effectués dans l’exemple.</p></li><li><strong>À vérifier dans le service réel</strong><p>Clés disponibles, effacements réappliqués et accès révoqués conservés.</p></li></ul>`);
 else if(action==='access-check')openDialog('Contrôle des accès expirés',`<p>Contrôle AC-021 · 14 novembre à 09:10.</p><p>Aucun accès résiduel détecté dans le scénario après expiration des partages et diagnostics temporaires.</p><div class="notice">Ce résultat fictif ne constitue pas une vérification de l’application réelle.</div>`);
 else if(action==='deletion-review')openDialog('Demande DEL-004',`<p>Suppression du compte et des données associées. Le contenu médical n’est pas consultable ici.</p><label class="check-row"><input type="checkbox" required>Règles de conservation vérifiées dans le scénario.</label><label class="check-row"><input type="checkbox" required>Exécution et preuve contrôlées dans le scénario.</label>`,'Enregistrer la preuve fictive',()=>{state.deletion=true;log('Suppression exécutée dans le scénario','DEL-004');simulationDone('Preuve de suppression enregistrée');});
}
document.addEventListener('click',e=>{const page=e.target.closest('[data-page]');if(page){go(page.dataset.page);return;}const period=e.target.closest('[data-period]');if(period){state.period=period.dataset.period;render();$(`[data-period="${state.period}"]`)?.focus({preventScroll:true});return;}const tab=e.target.closest('[data-tab]');if(tab){state.patientTab=tab.dataset.tab;render();$(`[data-tab="${state.patientTab}"]`)?.focus({preventScroll:true});return;}const action=e.target.closest('[data-action]');if(action&&!action.disabled){handleAction(action.dataset.action,action);return;}if(e.target.closest('[data-sort-patients]')){const body=$('#patient-table tbody'),rows=[...body.rows];rows.reverse().forEach(r=>body.append(r));e.target.closest('th').setAttribute('aria-sort',e.target.closest('th').getAttribute('aria-sort')==='ascending'?'descending':'ascending');}});
document.addEventListener('change',e=>{const el=e.target;if(el.matches('[data-org-status]')){const rec=state.orgRecs[Number(el.dataset.orgStatus)];rec.status=el.value;state.orgHistory.unshift({id:rec.id,status:rec.status,date:'14 novembre · 18:05'});render();notify('Avancement mis à jour dans la maquette.');}if(el.matches('[data-setting]')){state[el.dataset.setting]=el.checked;render();$(`[data-setting="${el.dataset.setting}"]`)?.focus({preventScroll:true});}if(el.matches('[data-pref]')){state[el.dataset.pref]=el.dataset.pref==='pauseFrequency'?Number(el.value):el.value;notify('Préférence mise à jour dans cet aperçu.');}if(el.matches('[data-channel]')){state.channels||={};state.channels[el.dataset.channel]=el.value;notify('Canal choisi dans cet aperçu. Aucun message envoyé.');}if(el.matches('[data-check]')){state.testChecks[state.tickets[state.ticket].id]||={};state.testChecks[state.tickets[state.ticket].id][el.dataset.check]=el.checked;}});
document.addEventListener('input',e=>{if(e.target.id!=='patient-search')return;const folded=v=>v.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase(),q=folded(e.target.value);let count=0;$$('#patient-table tbody tr').forEach(row=>{row.hidden=!folded(row.dataset.search).includes(q);if(!row.hidden)count++;});$('#patient-count').textContent=`${count} patient${count>1?'s':''}`;$('#patient-empty').hidden=count>0;});
document.addEventListener('keydown',e=>{const tab=e.target.closest('[data-tab]');if(!tab)return;const tabs=$$('[data-tab]');let i=tabs.indexOf(tab);if(e.key==='ArrowRight')i=(i+1)%tabs.length;else if(e.key==='ArrowLeft')i=(i-1+tabs.length)%tabs.length;else if(e.key==='Home')i=0;else if(e.key==='End')i=tabs.length-1;else return;e.preventDefault();state.patientTab=tabs[i].dataset.tab;render();$(`[data-tab="${state.patientTab}"]`).focus();});
$('.brand').onclick=e=>{e.preventDefault();go('home');};
render();menu(false);
